using AgentCore.Application.Ports;
using AgentCore.Application.Sessions;
namespace AgentCore.Infrastructure.Persistence;

public sealed class InMemoryDriveStore : IDriveOperationStore, ISyntheticDriveStore
{
    private readonly object gate = new(); private readonly Dictionary<Guid, DriveOperation> operations = []; private readonly Dictionary<(Guid, string), (DriveFile File, byte[] Bytes)> files = [];
    public ValueTask<DriveOperation?> GetAsync(Guid owner, Guid id, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) return ValueTask.FromResult(operations.TryGetValue(id, out var op) && op.AgentInstanceId == owner ? op : null); }
    public ValueTask<DriveOperation?> FindAsync(Guid owner, Guid credential, string hash, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) return ValueTask.FromResult(operations.Values.SingleOrDefault(op => op.AgentInstanceId == owner && op.CredentialId == credential && op.EffectHash == hash && op.State is not ("Succeeded" or "Rejected"))); }
    public ValueTask<DriveOperation> ClaimAsync(DriveOperation op, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) { if (operations.TryGetValue(op.OperationId, out var old)) { if (old.AgentInstanceId != op.AgentInstanceId || old.CredentialId != op.CredentialId || old.EffectHash != op.EffectHash) throw AgentCoreErrors.Conflict("Drive operation identity is already claimed."); return ValueTask.FromResult(old); } if (operations.Values.Any(old => old.AgentInstanceId == op.AgentInstanceId && old.CredentialId == op.CredentialId && old.EffectHash == op.EffectHash && old.State is not ("Succeeded" or "Rejected"))) throw AgentCoreErrors.Conflict("A matching Drive operation is in progress."); operations[op.OperationId] = op; return ValueTask.FromResult(op); } }
    public ValueTask<DriveOperation> UpdateAsync(DriveOperation op, long revision, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) { if (!operations.TryGetValue(op.OperationId, out var old) || old.AgentInstanceId != op.AgentInstanceId || old.CredentialId != op.CredentialId || old.Revision != revision || op.Revision != revision + 1 || old.EffectHash != op.EffectHash || old.FileId != op.FileId || old.AuthEpoch != op.AuthEpoch || old.SnapshotJson != op.SnapshotJson || !DriveOperationTransitions.SameIntent(old, op)) throw AgentCoreErrors.Conflict("Drive operation changed."); operations[op.OperationId] = op; return ValueTask.FromResult(op); } }
    public ValueTask DeleteOwnerAsync(Guid id, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) { foreach (var key in operations.Where(p => p.Value.AgentInstanceId == id).Select(p => p.Key).ToArray()) operations.Remove(key); } return ValueTask.CompletedTask; }
    public ValueTask<DriveFile?> GetAsync(Guid credential, string id, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) return ValueTask.FromResult(files.TryGetValue((credential, id), out var entry) ? entry.File : null); }
    public ValueTask<IReadOnlyList<DriveFile>> ListAsync(Guid credential, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) return ValueTask.FromResult<IReadOnlyList<DriveFile>>(files.Where(p => p.Key.Item1 == credential).Select(p => p.Value.File).OrderBy(f => f.Id).Take(4096).ToArray()); }
    public ValueTask<byte[]> ReadAsync(Guid credential, string id, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) return ValueTask.FromResult(files.TryGetValue((credential, id), out var entry) ? entry.Bytes.ToArray() : throw AgentCoreErrors.NotFound("Drive file was not found.")); }
    public ValueTask SaveAsync(Guid credential, DriveFile file, byte[]? bytes, string? version, CancellationToken ct) { ct.ThrowIfCancellationRequested(); lock (gate) { var exists = files.TryGetValue((credential, file.Id), out var old); if (exists && (version is null || old.File.Version != version) || !exists && version is not null) throw AgentCoreErrors.Conflict("Drive remote revision conflict."); files[(credential, file.Id)] = (file, bytes?.ToArray() ?? old.Bytes ?? []); } return ValueTask.CompletedTask; }
}
